#include <iostream>
#include <string>
#include <algorithm>
#include <vector>

int maxLength(const std::string& s) {
    std::string builder;
    bool insideBracket = false;
    for (size_t i = 0; i < s.length(); ++i) {
        char c = s[i];
        if (c == '(')
            insideBracket = true;
        else if (c == ')') {
            insideBracket = false;
            builder += '_';
        }
        if (!insideBracket && c != ')')
            builder += c;
    }
    size_t maxLen = 0;
    size_t start = 0;
    for (size_t i = 0; i <= builder.length(); ++i) {
        if (i == builder.length() || builder[i] == '_') {
            size_t segmentLength = i - start;
            if (segmentLength > maxLen)
                maxLen = segmentLength;
            start = i + 1;
        }
    }
    return static_cast<int>(maxLen);
}

int count(const std::string& s) {
    int count = 0;
    size_t start = 0;
    while (true) {
        size_t pos = s.find('_', start);
        if (pos == std::string::npos) {
            if (start < s.length())
                count++;
            break;
        } else {
            if (pos > start)
                count++;
            start = pos + 1;
        }
    }
    return count;
}

int words(const std::string& s) {
    int totalWords = 0;
    std::string temp;
    bool inBracket = false;
    for (size_t i = 0; i < s.length(); ++i) {
        char c = s[i];
        if (c == '(')
            inBracket = true;
        else if (c == ')') {
            inBracket = false;
            totalWords += count(temp);
            temp.clear();
        } else if (inBracket && c != '(') {
            temp += c;
        }
    }
    return totalWords;
}

int main() {
    int n;
    std::cin >> n;
    std::string s;
    std::cin >> s;
    std::cout << maxLength(s) << " " << words(s) << std::endl;
    return 0;
}

